// Liczba permutacji n elementów z dokładnie k inwersjami, modulo 10^9+7.
// dp[i][j] = Σ_{t=0}^{min(j, i-1)} dp[i-1][j-t]  (nowy największy element tworzy t inwersji)
#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1'000'000'007;

int main() {
    int n, k;
    cin >> n >> k;
    vector<long long> dp(k + 1, 0), pre(k + 2);
    dp[0] = 1;                                     // jeden element: 0 inwersji
    for (int i = 2; i <= n; i++) {
        pre[0] = 0;
        for (int j = 0; j <= k; j++) pre[j + 1] = (pre[j] + dp[j]) % MOD;   // sumy prefiksowe wiersza i-1
        for (int j = 0; j <= k; j++) {
            int lo = max(0, j - (i - 1));          // t <= i-1  =>  j - t >= j - (i-1)
            dp[j] = (pre[j + 1] - pre[lo] + MOD) % MOD;
        }
    }
    cout << dp[k] << "\n";
}

// Ile sposobów rozdać K cukierków n dzieciom, gdy dziecko i dostaje od 0 do a[i]? O(n·K).
#include <bits/stdc++.h>
using namespace std;
const long long MOD = 1'000'000'007;

int main() {
    int n, K;
    cin >> n >> K;
    vector<long long> dp(K + 1, 0), pre(K + 2);
    dp[0] = 1;
    for (int i = 0; i < n; i++) {
        int a;
        cin >> a;
        pre[0] = 0;
        for (int j = 0; j <= K; j++) pre[j + 1] = (pre[j] + dp[j]) % MOD;
        for (int j = 0; j <= K; j++)               // nowe dp[j] = Σ_{t=0}^{min(j,a)} dp[j-t]
            dp[j] = (pre[j + 1] - pre[max(0, j - a)] + MOD) % MOD;
    }
    cout << dp[K] << "\n";
}

