// Podział ciągu liczb nieujemnych na k fragmentów minimalizujący sumę kwadratów sum fragmentów.
// O(k · n log n) dzięki optymalizacji dziel i zwyciężaj.
#include <bits/stdc++.h>
using namespace std;

const long long INF = LLONG_MAX;
vector<long long> P, prv, cur;

long long cost(int j, int i) { long long s = P[i] - P[j]; return s * s; }   // fragment a[j..i)

// liczy cur[i] dla i w [l, r], wiedząc, że optymalne j leży w [optl, optr]
void compute(int l, int r, int optl, int optr) {
    if (l > r) return;
    int mid = (l + r) / 2, best = optl;
    long long bestVal = INF;
    for (int j = optl; j <= min(mid - 1, optr); j++) {
        if (prv[j] == INF) continue;
        long long v = prv[j] + cost(j, mid);
        if (v < bestVal) { bestVal = v; best = j; }
    }
    cur[mid] = bestVal;
    compute(l, mid - 1, optl, best);
    compute(mid + 1, r, best, optr);
}

int main() {
    int n, k;
    cin >> n >> k;
    P.assign(n + 1, 0);
    for (int i = 0; i < n; i++) { long long x; cin >> x; P[i + 1] = P[i] + x; }
    prv.assign(n + 1, INF);
    prv[0] = 0;                                  // 0 fragmentów, pusty prefiks
    for (int c = 1; c <= k; c++) {
        cur.assign(n + 1, INF);
        compute(1, n, 0, n - 1);
        prv = cur;
    }
    cout << prv[n] << "\n";
}

