const long long INF = LLONG_MAX;
vector<long long> P, prv, cur;
long long cost(int j, int i) { long long s = P[i] - P[j]; return s * s; }
void compute(int l, int r, int optl, int optr) {
    if (l > r) return;
    int mid = (l + r) / 2, best = optl; long long bv = INF;
    for (int j = optl; j <= min(mid - 1, optr); j++)
        if (prv[j] != INF && prv[j] + cost(j, mid) < bv) { bv = prv[j] + cost(j, mid); best = j; }
    cur[mid] = bv;
    compute(l, mid - 1, optl, best); compute(mid + 1, r, best, optr);
}
long long fast(int n, int k) {
    prv.assign(n + 1, INF); prv[0] = 0;
    for (int c = 1; c <= k; c++) { cur.assign(n + 1, INF); compute(1, n, 0, n - 1); prv = cur; }
    return prv[n];
}
long long slow(int n, int k) {
    vector<vector<long long>> dp(k + 1, vector<long long>(n + 1, INF)); dp[0][0] = 0;
    for (int c = 1; c <= k; c++) for (int i = 1; i <= n; i++) for (int j = 0; j < i; j++)
        if (dp[c - 1][j] != INF) dp[c][i] = min(dp[c][i], dp[c - 1][j] + cost(j, i));
    return dp[k][n];
}
int main() {
    mt19937 rng(12345);
    for (int it = 0; it < 2000; it++) {
        int n = rng() % 12 + 1, k = rng() % n + 1;
        P.assign(n + 1, 0);
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + rng() % 11;
        if (fast(n, k) != slow(n, k)) { cout << "BŁĄD n=" << n << " k=" << k << "\n"; return 0; }
    }
    cout << "OK\n";
}

