// Łączenie sąsiednich stosów (koszt złączenia = suma), optymalizacja Knutha: O(n^2).
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<long long> P(n + 1, 0);
    for (int i = 0; i < n; i++) { long long x; cin >> x; P[i + 1] = P[i] + x; }
    vector<vector<long long>> dp(n, vector<long long>(n, 0));
    vector<vector<int>> opt(n, vector<int>(n, 0));
    for (int i = 0; i < n; i++) opt[i][i] = i;
    for (int len = 2; len <= n; len++)
        for (int l = 0; l + len - 1 < n; l++) {
            int r = l + len - 1;
            dp[l][r] = LLONG_MAX;
            int from = opt[l][r - 1], to = min(r - 1, opt[l + 1][r]);
            for (int k = from; k <= to; k++) {          // tylko zakres z twierdzenia Knutha
                long long v = dp[l][k] + dp[k + 1][r];
                if (v < dp[l][r]) { dp[l][r] = v; opt[l][r] = k; }
            }
            dp[l][r] += P[r + 1] - P[l];
        }
    cout << dp[0][n - 1] << "\n";
}

