// Żaba 3: kamienie o rosnących wysokościach h; skok j -> i kosztuje (h_i - h_j)^2 + C. Min. koszt 1 -> n.
// CHT z deque: nachylenia -2h_j maleją, zapytania x = h_i rosną.
#include <bits/stdc++.h>
using namespace std;

struct Line {
    long long m, c;
    long long eval(long long x) const { return m * x + c; }
};

// czy l2 jest zbędna między l1 i l3 (nachylenia m1 > m2 > m3, minimum)
bool bad(const Line &l1, const Line &l2, const Line &l3) {
    return (__int128)(l3.c - l1.c) * (l1.m - l2.m) <= (__int128)(l2.c - l1.c) * (l1.m - l3.m);
}

int main() {
    int n;
    long long C;
    cin >> n >> C;
    vector<long long> h(n);
    for (auto &x : h) cin >> x;
    vector<long long> dp(n, 0);
    deque<Line> hull;
    hull.push_back({-2 * h[0], dp[0] + h[0] * h[0]});
    for (int i = 1; i < n; i++) {
        while (hull.size() >= 2 && hull[1].eval(h[i]) <= hull[0].eval(h[i])) hull.pop_front();
        dp[i] = hull.front().eval(h[i]) + h[i] * h[i] + C;
        Line nl = {-2 * h[i], dp[i] + h[i] * h[i]};
        while (hull.size() >= 2 && bad(hull[hull.size() - 2], hull.back(), nl)) hull.pop_back();
        hull.push_back(nl);
    }
    cout << dp[n - 1] << "\n";
}

// Drzewo Li Chao dla minimum na całkowitych x z [lo, hi]. Dowolna kolejność prostych i zapytań.
struct LiChao {
    struct Line { long long m, c; long long eval(long long x) const { return m * x + c; } };
    struct Node { Line ln; int left = -1, right = -1; };
    vector<Node> t;                               // węzły tworzone leniwie
    long long lo, hi;
    LiChao(long long lo, long long hi) : lo(lo), hi(hi) {}
    void add(long long m, long long c) {
        Line nw{m, c};
        if (t.empty()) { t.push_back({nw}); return; }
        int v = 0;
        long long l = lo, r = hi;
        while (true) {
            long long mid = l + (r - l) / 2;
            bool lef = nw.eval(l) < t[v].ln.eval(l);
            bool md = nw.eval(mid) < t[v].ln.eval(mid);
            if (md) swap(t[v].ln, nw);            // w węźle zostaje prosta lepsza w środku
            if (l == r) return;
            if (lef != md) {                      // gorsza w środku może wygrywać tylko w [l, mid]
                if (t[v].left == -1) { t[v].left = t.size(); t.push_back({nw}); return; }
                v = t[v].left; r = mid;
            } else {                              // ... albo tylko w [mid+1, r]
                if (t[v].right == -1) { t[v].right = t.size(); t.push_back({nw}); return; }
                v = t[v].right; l = mid + 1;
            }
        }
    }
    long long query(long long x) const {          // LLONG_MAX, gdy brak prostych
        long long res = LLONG_MAX, l = lo, r = hi;
        int v = t.empty() ? -1 : 0;
        while (v != -1) {
            res = min(res, t[v].ln.eval(x));
            long long mid = l + (r - l) / 2;
            if (x <= mid) { v = t[v].left; r = mid; } else { v = t[v].right; l = mid + 1; }
        }
        return res;
    }
};

