// Pola 1..n z kosztami c_i; startujesz na polu 1, kończysz na n, skok o 1..k pól do przodu.
// Minimalna suma kosztów odwiedzonych pól. dp[i] = c[i] + min(dp[i-k..i-1]) — O(n) kolejką monotoniczną.
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;
    vector<long long> c(n), dp(n);
    for (auto &x : c) cin >> x;
    deque<int> dq;                       // indeksy; dp[dq[0]] < dp[dq[1]] < ...
    dp[0] = c[0];
    dq.push_back(0);
    for (int i = 1; i < n; i++) {
        while (dq.front() < i - k) dq.pop_front();       // wypadło z okna [i-k, i-1]
        dp[i] = c[i] + dp[dq.front()];
        while (!dq.empty() && dp[dq.back()] >= dp[i]) dq.pop_back();
        dq.push_back(i);
    }
    cout << dp[n - 1] << "\n";
}

// Plecak ograniczony w O(n·W): przedmiot (w, v, c) — osobna kolejka monotoniczna dla każdej reszty r = cap mod w.
// dp_new[r + t·w] = max_{t-c <= s <= t} (dp_old[r + s·w] - s·v) + t·v
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, W;
    cin >> n >> W;
    vector<long long> dp(W + 1, 0), nd(W + 1);
    for (int it = 0; it < n; it++) {
        long long w, v, c;
        cin >> w >> v >> c;
        for (long long r = 0; r < w && r <= W; r++) {
            deque<pair<long long, long long>> dq;          // (s, dp_old[r + s·w] - s·v), wartości malejące
            for (long long t = 0; r + t * w <= W; t++) {
                long long val = dp[r + t * w] - t * v;
                while (!dq.empty() && dq.back().second <= val) dq.pop_back();
                dq.push_back({t, val});
                while (dq.front().first < t - c) dq.pop_front();   // co najwyżej c sztuk
                nd[r + t * w] = dq.front().second + t * v;
            }
        }
        dp = nd;
    }
    cout << dp[W] << "\n";
}

